use serde::{Deserialize, Serialize};

/// SIGIL release plan — Cortex-optimized for v1.0 launch.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SigilReleasePlan {
    pub version: String,
    pub phases: Vec<PhasePlan>,
    pub cortex_insights: CortexInsights,
    pub priority_actions: Vec<PriorityAction>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PhasePlan {
    pub phase: char,
    pub name: String,
    pub releases: Vec<PlannedRelease>,
    pub estimated_days: u32,
    pub cortex_gain_pct: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PlannedRelease {
    pub version: String,
    pub title: String,
    pub description: String,
    pub crate_impact: Vec<String>,
    pub architect_findings: Vec<String>,
    pub estimated_hours: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CortexInsights {
    pub total_findings: usize,
    pub sigil_specific_findings: usize,
    pub top_dimension: String,
    pub top_gain_pct: f64,
    pub top_crate: String,
    pub estimated_total_speedup: f64,
    pub mcp_tools_available: usize,
    pub tests_passing: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PriorityAction {
    pub rank: usize,
    pub action: String,
    pub crate_name: String,
    pub impact: String,
    pub effort: String,
    pub dimension: String,
}

