#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_release_plan_generation() {
        let plan = generate_release_plan();
        assert_eq!(plan.version, "1.0.0");
        assert_eq!(plan.phases.len(), 5); // F, G, H, I, J
        assert_eq!(plan.phases[0].phase, 'F');
        assert_eq!(plan.phases[4].phase, 'J');
    }

    #[test]
    fn test_cortex_insights() {
        let plan = generate_release_plan();
        assert!(plan.cortex_insights.total_findings > 0);
        assert!(plan.cortex_insights.sigil_specific_findings > 0);
        assert_eq!(plan.cortex_insights.top_dimension, "Vectorization (AVX-512 SIMD)");
        assert!(plan.cortex_insights.top_gain_pct > 400.0);
    }

    #[test]
    fn test_priority_actions_sorted() {
        let plan = generate_release_plan();
        for i in 1..plan.priority_actions.len() {
            assert!(plan.priority_actions[i - 1].rank < plan.priority_actions[i].rank);
        }
    }

    #[test]
    fn test_phase_f_releases() {
        let plan = generate_release_plan();
        let phase_f = &plan.phases[0];
        assert_eq!(phase_f.releases.len(), 4);
        assert!(phase_f.releases[0].title.contains("Swarm Agent"));
    }

    #[test]
    fn test_launch_release() {
        let plan = generate_release_plan();
        let launch = plan.phases.iter().find(|p| p.phase == 'J').unwrap();
        let v1 = launch.releases.iter().find(|r| r.version == "1.0.0").unwrap();
        assert!(v1.title.contains("Public Launch"));
    }
}
